//! Completeness: a proof generated by the prover must verify.
//! Mirror of sumcheck-ring's completeness tests.

use field::{AbstractExtensionField, AbstractField, BB};
use rand::rngs::StdRng;
use rand::{Rng, SeedableRng};

use sumcheck_field::{prove, verify, BB4UniformSampler, Mle, BB4};

fn rand_bb4(rng: &mut StdRng) -> BB4 {
    let bases: [BB; 4] = [rng.gen(), rng.gen(), rng.gen(), rng.gen()];
    <BB4 as AbstractExtensionField<BB>>::from_base_slice(&bases)
}

fn hypercube_sum_product(f: &Mle, g: &Mle) -> BB4 {
    assert_eq!(f.len(), g.len());
    let mut acc = BB4::zero();
    for (a, b) in f.evals().iter().zip(g.evals().iter()) {
        acc += (*a) * (*b);
    }
    acc
}

fn round_trip_at(num_vars: usize, seed: u64) {
    let mut rng = StdRng::seed_from_u64(seed);
    let n = 1usize << num_vars;
    let f = Mle::new((0..n).map(|_| rand_bb4(&mut rng)).collect());
    let g = Mle::new((0..n).map(|_| rand_bb4(&mut rng)).collect());

    let claim = hypercube_sum_product(&f, &g);

    let mut prover_sampler = BB4UniformSampler::new(0xC0FFEE ^ seed);
    let (proof, prover_challenges) = prove(&f, &g, claim, &mut prover_sampler);

    let mut verifier_sampler = BB4UniformSampler::new(0xC0FFEE ^ seed);
    let verifier_challenges = verify(&proof, num_vars, &mut verifier_sampler).expect("verify");

    assert_eq!(prover_challenges, verifier_challenges);
    assert_eq!(proof.num_rounds(), num_vars);
}

#[test]
fn round_trip_4_vars() {
    round_trip_at(4, 0xa);
}

#[test]
fn round_trip_8_vars() {
    round_trip_at(8, 0xb);
}

#[test]
fn round_trip_12_vars() {
    round_trip_at(12, 0xc);
}

#[test]
fn round_trip_with_zero_g_yields_zero_claim() {
    let mut rng = StdRng::seed_from_u64(7);
    let n = 1usize << 6;
    let f = Mle::new((0..n).map(|_| rand_bb4(&mut rng)).collect());
    let g = Mle::zeros(6);

    let mut sampler = BB4UniformSampler::new(42);
    let (proof, _) = prove(&f, &g, BB4::zero(), &mut sampler);

    let mut sampler2 = BB4UniformSampler::new(42);
    verify(&proof, 6, &mut sampler2).expect("zero claim must verify");
}
